head.script:
scwin.getType = function(info) {
    var rowIndex = info.rowIndex;
    var colIndex = info.colIndex;
    var returnInfo;
    var inputType = dsl_inputTypeList.getCellData(rowIndex, colIndex) || "text";
    switch (inputType) {
        case "radio":
            returnInfo = {
                id: "dynamic_radio_" + rowIndex + "_" + colIndex,
                inputType: "radio",
                options: {
                    groupName: "radio_" + rowIndex
                }
            };
            break;
        case "checkbox":
            returnInfo = {
                id: "dynamic_checkbox_" + rowIndex + "_" + colIndex,
                inputType: "checkbox",
                options: {}
            };
            break;
        case "button":
            returnInfo = {
                id: "dynamic_button_" + rowIndex + "_" + colIndex,
                inputType: "button",
                options: {}
            };
            break;
        case "calendar":
            returnInfo = {
                id: "dynamic_calendar_" + rowIndex + "_" + colIndex,
                inputType: "calendar",
                options: {
                    viewType: "icon"
                }
            };
            break;
        case "image":
            returnInfo = {
                id: "dynamic_image_" + rowIndex + "_" + colIndex,
                inputType: "image",
                options: {
                    imageSrc: "/SAMPLE/W5/project/dynamic/img.gif"
                }
            };
            break;
        case "link":
            returnInfo = {
                id: "dynamic_link_" + rowIndex + "_" + colIndex,
                inputType: "link",
                options: {}
            };
            break;
        case "select":
            returnInfo = {
                id: "dynamic_select_" + rowIndex + "_" + colIndex,
                inputType: "select",
                options: {
                    viewType: "icon"
                },
                itemSet: {
                    nodeset: "data:dsl_dataList3",
                    label: "label",
                    value: "value"
                }
            };
            break;
        case "autoComplete":
            returnInfo = {
                id: "dynamic_autoComplete_" + rowIndex + "_" + colIndex,
                inputType: "autoComplete",
                options: {
                    viewType: "icon"
                },
                itemSet: {
                    nodeset: "data:dsl_dataList3",
                    label: "label",
                    value: "value"
                }
            };
            break;
        case "checkcombobox":
            returnInfo = {
                id: "dynamic_checkcombobox_" + rowIndex + "_" + colIndex,
                inputType: "checkcombobox",
                options: {
                    viewType: "icon"
                },
                itemSet: {
                    nodeset: "data:dsl_dataList3",
                    label: "label",
                    value: "value"
                }
            };
            break;
        case "textarea":
            returnInfo = {
                id: "dynamic_textarea_" + rowIndex + "_" + colIndex,
                inputType: "textarea",
                options: {}
            };
            break;
        case "text":
            returnInfo = {
                id: "dynamic_text_" + rowIndex + "_" + colIndex,
                inputType: "text",
                options: {
                    maxByteLength: "6"
                }
            };
            break;
        case "textImage":
            returnInfo = {
                id: "dynamic_textImage_" + rowIndex + "_" + colIndex,
                inputType: "textImage",
                options: {
                    viewType: "icon",
                    imageSrc: "/SAMPLE/W5/project/dynamic/alz.jpg",
                    textAlign: "center"
                }
            };
            break;
    }
    return returnInfo;
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scvar == "undefined") {
        window.scvar = {};
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

scwin.btn_b1_onclick = function(e) {
    var rowIndex = WebSquare.util.getNumber(edt_rowTb.getValue());
    var inputType = cob_inputType1.getValue();
    for (var i = 0; i < dsl_inputTypeList.getColCnt(); i++) {
        dsl_inputTypeList.setCellData(rowIndex, i, inputType);
    }
    grd_inputList.refreshRow(rowIndex);
};
scwin.btn_b2_onclick = function(e) {
    var colIndex = WebSquare.util.getNumber(edt_colTb.getValue());
    var inputType = cob_inputType2.getValue();
    for (var i = 0; i < dsl_inputTypeList.getRowCount(); i++) {
        dsl_inputTypeList.setCellData(i, colIndex, inputType);
    }
    grd_inputList.refreshColumn(colIndex);
    //grd_inputList.
};
scwin.btn_b3_onclick = function(e) {
    var colIndex = WebSquare.util.getNumber(edt_cellColTb.getValue());
    var rowIndex = WebSquare.util.getNumber(edt_cellRowTb.getValue());
    var inputType = cob_inputType3.getValue();
    dsl_inputTypeList.setCellData(rowIndex, colIndex, inputType);
    grd_inputList.refreshCell(rowIndex, colIndex);
};
scwin.dsl_inputTypeList_oncelldatachange = function(info) {
    //event;
};
scwin.btn_b4_onclick = function(e) {
    for (var i = 0; i < dsl_inputTypeList.getColCnt(); i++) {
        dsl_inputTypeList.setCellData(0, i, "text");
    }
    dsl_dataList1.setCellData(0, 0, "radio checkbox button calendar image link select autoComplete checkcombobox textarea");
    grd_inputList.refreshRow(0);
};
scwin.onpageload = function() {
    if (typeof scwin.onpageload === "function") {
        //scwin.onpageload();
    }
    /******************************************************************************
     * 프로그램명 : 개발 가이드 샘플.[그리드 사용자정의 inputType]
     * ProgramID  : grd_customInputType
     * 작성자	  : 홍길동
     * 작성일	  : 2016-01-01
     * 변경로그   : 최초작성 2016-01-01
     ******************************************************************************/
    if (!scwin.promise) {
        scwin.promise = {};
    }

    if (typeof scvar == "undefined") {
        window.scvar = {};
    }

    scvar.dataArr = [
        "radio", "radio",
        "checkbox", "checkbox",
        "button", "button",
        "calendar", "calendar",
        "image", "image",
        "link", "link",
        "select", "select",
        "autoComplete", "autoComplete",
        "checkcombobox", "checkcombobox",
        "textarea", "textarea",
        "text", "text",
        "textImage", "textImage"
    ];
    dsl_dataList2.setData(scvar.dataArr);
    dsl_dataList3.setData(scvar.dataArr);
    scvar._dataArr = [];
    for (var i = 0; i < 300; i++) {
        scvar._dataArr.push("");
    }
    dsl_dataList1.setData(scvar._dataArr.slice(0));
    dsl_inputTypeList.setData(scvar._dataArr.slice(0));
    /**
     * 1. Row 갱신 버튼 클릭
     */
    /**
     * 2. Column 갱신 버튼 클릭
     */
    /**
     * 3. Cell 갱신 버튼 클릭
     */
    /**
     * dsl_inputTypeList 셀 데이터 변경시 이벤트
     */
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
